commands.command:
P=/home/siegfriedneto/.claude/plugins/cache/siegard-generator/siegard/5.2.0
d(){ python3 -B $P/bin/spec.py --decide "$1" . ; }
d domain/owner-access/_context <<'JSON'
{"field": "strategic", "unstated": "The material does not say whether signing in is where the business differs or a solved problem.", "decided": "supporting", "why": "Signing in only gates the application behind an external identity provider and holds nothing the business differs on, so it is specific to this application without being core."}
JSON
d contracts/owner-access/sign-in <<'JSON'
{"field": "answers", "unstated": "The material does not say which boundary holds the messages the owner reads at the sign-in screen, nor whether a message is a fact of the domain or only a label.", "decided": "The sign-in screen is a published api whose caller is the owner, and every message that tells the owner what was refused or what happened is an answer of it, while control labels, headings and placeholders are held by no node.", "why": "A message changes what the owner learns, which is what separates a fact from presentation, whereas a relabelled control keeps doing the same thing."}
JSON
d domain/owner-access/sign-in-credentials <<'JSON'
{"field": "attributes", "unstated": "The material names the two fields login and senha, in Portuguese, while the specification is written in English.", "decided": "The attributes are email and password, and the labels Login and Senha stay in the description.", "why": "The material's own words are the on-screen labels and the specification translates names, so the e-mail address the field holds is named for what it is."}
JSON
d rules/owner-access/sign-in-attempt-in-flight-accepts-no-second-submission <<'JSON'
{"field": "statement", "unstated": "The material says the fields and the submit button are disabled while an attempt is in flight, and does not say what that protects.", "decided": "The condition is that an attempt in flight accepts no second submission.", "why": "Disabling the controls is the means, and what the owner can no longer do is submit again before the first attempt ends, which is the obligation a reader can hold the screen to."}
JSON
d rules/owner-access/network-looking-failure-is-a-network-failure <<'JSON'
{"field": "statement", "unstated": "The material does not say whether a failure that did not come out of the exchange with the identity provider is read by its message or only by its type.", "decided": "It is a network failure when it is a type error or its message mentions a failed fetch or the network, and a failure the exchange raised is never read by its message.", "why": "The code reads the message only after every recognised failure of the exchange has been classified by its cause, so the message reading applies to the remainder and nothing else."}
JSON
python3 -B $P/bin/spec.py . | tail -1; python3 -B $P/bin/spec.py --project . | tail -5
